const { useEffect, useRef, useState } = React;
const INITIAL = "hello";
const TYPED = "world";

// HTML 文档视图：标签、特性名、特性值分色；样式类特性与演示无关，不显示
const HtmlView = ({ html }) => {
  const parts = html.replace(/ (?:class|style)="[^"]*"/g, "").split(/(<\/?[\w-]+|[\w-]+(?==)|"[^"]*"|\/?>)/g).filter(Boolean);
  return (
    <pre className="m-0 min-h-[64px] whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
      {parts.map((part, index) => {
        if (/^<\/?[\w-]+$|^\/?>$/.test(part)) return <span key={index} className="text-ink-3">{part}</span>;
        if (/^"/.test(part)) return <span key={index} className="text-ok">{part}</span>;
        if (/^[\w-]+$/.test(part) && parts[index + 1]?.startsWith('"')) return <span key={index} className="text-accent-text">{part}</span>;
        return <span key={index}>{part}</span>;
      })}
    </pre>
  );
};

// 对照读数：值变化时闪一下，便于看出哪一侧跟着变了
const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="font-tau-mono text-tau-sm text-ink-3">{label}</dt>
        <dd key={String(value)} className="cb-pulse m-0 truncate rounded-tau-sm px-1 font-tau-mono text-tau-sm text-ink-1">
          {value === undefined ? <span className="text-ink-3">undefined</span> : value === null ? <span className="text-ink-3">null</span> : JSON.stringify(value)}
        </dd>
      </React.Fragment>
    ))}
  </dl>
);

const STYLE = `
  @scope {
    .cb-pulse { animation: cb-attr-pulse 900ms var(--tau-ease-out); }
    @media (prefers-reduced-motion: reduce) {
      .cb-pulse { animation: none; }
    }
  }
  @keyframes cb-attr-pulse {
    from { background: var(--tau-accent-soft); }
    to { background: transparent; }
  }
`;

const MethodButton = ({ children, onClick }) => (
  <ui.Button variant="secondary" size="sm" onClick={onClick}>
    <span className="font-tau-mono">{children}</span>
  </ui.Button>
);

const DirtyState = ({ dirty }) => (
  <span className="flex items-center gap-1.5 text-tau-sm text-ink-3">
    状态：<ui.Tag color={dirty ? "orange" : "green"}>{dirty ? "dirty" : "clean"}</ui.Tag>
  </span>
);

const Component = () => {
  const formRef = useRef(null);
  const inputRef = useRef(null);
  const [html, setHtml] = useState("");
  const [values, setValues] = useState({});
  const [dirty, setDirty] = useState(false);
  const [inputKey, setInputKey] = useState(0);

  const sync = () => {
    const input = inputRef.current;
    if (!input) return;
    setHtml(input.outerHTML);
    setValues({ value: input.value, defaultValue: input.defaultValue, attribute: input.getAttribute("value") });
  };
  // 初值写成 value 特性（等同 HTML 里的 <input value="hello">），不能用 React 的 defaultValue
  useEffect(() => {
    inputRef.current.setAttribute("value", INITIAL);
    setDirty(false);
    sync();
  }, [inputKey]);

  const nextAttribute = values.attribute === "hey" ? "hello" : "hey";

  const typeByUser = () => {
    setDirty(true);
    sync();
  };
  const changeByProperty = () => {
    inputRef.current.value = TYPED;
    setDirty(true);
    sync();
  };
  const changeByAttribute = () => {
    inputRef.current.setAttribute("value", nextAttribute);
    sync();
  };
  // 表单重置：value 恢复为 defaultValue，同时清除 dirty 标记
  const resetForm = () => {
    formRef.current.reset();
    setDirty(false);
    sync();
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-2">
        <form
          ref={formRef}
          onSubmit={event => event.preventDefault()}
          className="flex min-h-[200px] flex-col items-center justify-center gap-3 rounded-tau-md border border-line-1 p-4"
        >
          <input
            key={inputKey}
            ref={inputRef}
            type="text"
            onInput={typeByUser}
            className="h-9 w-full max-w-[280px] rounded-tau-sm border border-line-1 bg-surface px-3 text-tau-body text-ink-1 outline-none focus:border-accent"
          />
          <DirtyState dirty={dirty} />
          <span className="text-tau-sm text-ink-3">在输入框里打字，与赋值 value 属性效果相同</span>
        </form>
        <div className="flex min-w-0 flex-col gap-2">
          <span className="text-tau-sm text-ink-3">HTML 文档</span>
          <HtmlView html={html} />
          <Readout
            rows={[
              ["input.value", values.value],
              ["input.defaultValue", values.defaultValue],
              ['getAttribute("value")', values.attribute],
            ]}
          />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <MethodButton onClick={changeByProperty}>input.value = "{TYPED}"</MethodButton>
        <MethodButton onClick={changeByAttribute}>input.setAttribute("value", "{nextAttribute}")</MethodButton>
        <MethodButton onClick={resetForm}>form.reset()</MethodButton>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} className="ml-auto" onClick={() => setInputKey(key => key + 1)}>
          重建元素
        </ui.Button>
      </div>
    </div>
  );
};

