const { useEffect, useRef, useState } = React;

// HTML 文档视图：标签、特性名、特性值分色；样式类特性与演示无关，不显示
const HtmlView = ({ html }) => {
  const parts = html.replace(/ (?:class|style)="[^"]*"/g, "").split(/(<\/?[\w-]+|[\w-]+(?==)|"[^"]*"|\/?>)/g).filter(Boolean);
  return (
    <pre className="m-0 min-h-[120px] whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
      {parts.map((part, index) => {
        if (/^<\/?[\w-]+$|^\/?>$/.test(part)) return <span key={index} className="text-ink-3">{part}</span>;
        if (/^"/.test(part)) return <span key={index} className="text-ok">{part}</span>;
        if (/^[\w-]+$/.test(part) && parts[index + 1]?.startsWith('"')) return <span key={index} className="text-accent-text">{part}</span>;
        return <span key={index}>{part}</span>;
      })}
    </pre>
  );
};

// 对照读数：值变化时闪一下，便于看出哪一侧跟着变了
const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="font-tau-mono text-tau-sm text-ink-3">{label}</dt>
        <dd key={String(value)} className="cb-pulse m-0 truncate rounded-tau-sm px-1 font-tau-mono text-tau-sm text-ink-1">
          {value === undefined ? <span className="text-ink-3">undefined</span> : value === null ? <span className="text-ink-3">null</span> : JSON.stringify(value)}
        </dd>
      </React.Fragment>
    ))}
  </dl>
);

const STYLE = `
  @scope {
    .cb-pulse { animation: cb-attr-pulse 900ms var(--tau-ease-out); }
    @media (prefers-reduced-motion: reduce) {
      .cb-pulse { animation: none; }
    }
  }
  @keyframes cb-attr-pulse {
    from { background: var(--tau-accent-soft); }
    to { background: transparent; }
  }
`;

const MethodButton = ({ children, onClick }) => (
  <ui.Button variant="secondary" size="sm" onClick={onClick}>
    <span className="font-tau-mono">{children}</span>
  </ui.Button>
);

const FRUITS = ["苹果", "香蕉", "橘子"];

const Component = () => {
  const formRef = useRef(null);
  const hostRef = useRef(null);
  const selectRef = useRef(null);
  const dirtyRef = useRef(FRUITS.map(() => false));
  const [html, setHtml] = useState("");
  const [values, setValues] = useState({});
  const [options, setOptions] = useState([]);
  const [selectKey, setSelectKey] = useState(0);

  const sync = () => {
    const select = selectRef.current;
    if (!select) return;
    setHtml(select.outerHTML.replace(/<option/g, "\n  <option").replace("</select>", "\n</select>"));
    setValues({ value: select.value, selectedIndex: select.selectedIndex });
    setOptions(
      [...select.options].map((option, index) => ({
        text: option.text,
        defaultSelected: option.defaultSelected,
        selected: option.selected,
        dirty: dirtyRef.current[index],
      })),
    );
  };
  // option 的 dirtiness 是浏览器内部标记，读不到，这里按标准规定的触发时机记账
  const markDirty = index => {
    if (index >= 0) dirtyRef.current[index] = true;
  };

  // 演示元素手动创建：React 重渲染时会改写受管 select 的选中状态，干扰演示
  useEffect(() => {
    const select = document.createElement("select");
    select.className = "h-9 w-full cursor-pointer rounded-tau-sm border border-line-1 bg-surface px-2 text-tau-body text-ink-1 outline-none focus:border-accent";
    FRUITS.forEach((fruit, index) => {
      const option = document.createElement("option");
      option.textContent = fruit;
      if (index === 1) option.setAttribute("selected", "");
      select.append(option);
    });
    const onChange = () => {
      markDirty(select.selectedIndex);
      sync();
    };
    select.addEventListener("change", onChange);
    hostRef.current.append(select);
    selectRef.current = select;
    dirtyRef.current = FRUITS.map(() => false);
    sync();
    return () => {
      select.removeEventListener("change", onChange);
      select.remove();
      selectRef.current = null;
    };
  }, [selectKey]);

  const run = action => {
    action(selectRef.current);
    sync();
  };
  const setByValue = () =>
    run(select => {
      select.value = "橘子";
      markDirty(2);
    });
  const setByIndex = () =>
    run(select => {
      select.selectedIndex = 0;
      markDirty(0);
    });
  const setOptionSelected = () =>
    run(select => {
      select.options[0].selected = true;
      markDirty(0);
    });
  const toggleAttribute = index => run(select => select.options[index].toggleAttribute("selected"));
  const resetForm = () =>
    run(() => {
      formRef.current.reset();
      dirtyRef.current = FRUITS.map(() => false);
    });

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-2">
        <form
          ref={formRef}
          onSubmit={event => event.preventDefault()}
          className="flex min-h-[160px] flex-col items-center justify-center gap-3 rounded-tau-md border border-line-1 p-4"
        >
          <div ref={hostRef} className="flex w-full max-w-[240px]" />
          <span className="text-tau-sm text-ink-3">在下拉框里选择，被选中的 option 变为 dirty</span>
        </form>
        <div className="flex min-w-0 flex-col gap-2">
          <span className="text-tau-sm text-ink-3">HTML 文档</span>
          <HtmlView html={html} />
          <Readout
            rows={[
              ["select.value", values.value],
              ["select.selectedIndex", values.selectedIndex],
            ]}
          />
        </div>
      </div>
      <div className="grid grid-cols-[minmax(0,1fr)_auto_auto_auto] items-center gap-x-4 gap-y-2 rounded-tau-md border border-line-1 px-3 py-2.5">
        <span className="text-tau-sm text-ink-3">option</span>
        <span className="text-tau-sm text-ink-3">selected 特性</span>
        <span className="font-tau-mono text-tau-sm text-ink-3">.selected</span>
        <span className="text-tau-sm text-ink-3">dirtiness</span>
        {options.map((option, index) => (
          <React.Fragment key={option.text}>
            <span className="flex min-w-0 items-center gap-2 text-tau-body text-ink-1">
              <span className="grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-3">{index}</span>
              {option.text}
            </span>
            <ui.Switch
              size="sm"
              checked={option.defaultSelected}
              onCheckedChange={() => toggleAttribute(index)}
              aria-label={`切换${option.text}的 selected 特性`}
            />
            <span key={String(option.selected)} className={`cb-pulse rounded-tau-sm px-1 font-tau-mono text-tau-sm ${option.selected ? "text-accent-text" : "text-ink-3"}`}>
              {String(option.selected)}
            </span>
            <span>
              <ui.Tag color={option.dirty ? "orange" : "green"}>{option.dirty ? "dirty" : "clean"}</ui.Tag>
            </span>
          </React.Fragment>
        ))}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <MethodButton onClick={setByValue}>select.value = "橘子"</MethodButton>
        <MethodButton onClick={setByIndex}>select.selectedIndex = 0</MethodButton>
        <MethodButton onClick={setOptionSelected}>options[0].selected = true</MethodButton>
        <MethodButton onClick={resetForm}>form.reset()</MethodButton>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} className="ml-auto" onClick={() => setSelectKey(key => key + 1)}>
          重建元素
        </ui.Button>
      </div>
    </div>
  );
};

