const link = document.querySelector('a');
const img = document.querySelector('img');

// 设置相对路径
link.setAttribute('href', '/docs/guide');
img.setAttribute('src', '/images/logo.png');

// attribute 保留原始值，property 返回绝对 URL
console.log(link.getAttribute('href')); // '/docs/guide'
console.log(link.href);                 // 'https://example.com/docs/guide'

console.log(img.getAttribute('src'));   // '/images/logo.png'
console.log(img.src);                   // 'https://example.com/images/logo.png'

// 通过 property 设置相对路径
link.href = '/new/path';
console.log(link.getAttribute('href')); // 'https://example.com/new/path' (被解析为绝对 URL)
console.log(link.href);                 // 'https://example.com/new/path'

// 设置绝对 URL
link.setAttribute('href', 'https://other.com/page');
console.log(link.getAttribute('href')); // 'https://other.com/page'
console.log(link.href);                 // 'https://other.com/page'

