const HtmlView = ({ html }) => {
  const parts = html.replace(/ (?:class|style)="[^"]*"/g, "").split(/(<\/?[\w-]+|[\w-]+(?==)|"[^"]*"|\/?>)/g).filter(Boolean);
  return (
    <pre className="m-0 min-h-[48px] whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
      {parts.map((part, index) => {
