        return <span key={index}>{part}</span>;
      })}
    </pre>
  );
};

// 对照读数：值变化时闪一下，便于看出哪一侧跟着变了
const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="font-tau-mono text-tau-sm text-ink-3">{label}</dt>
        <dd key={String(value)} className="cb-pulse m-0 min-w-0 break-all rounded-tau-sm px-1 font-tau-mono text-tau-sm text-ink-1">
          {value === undefined ? <span className="text-ink-3">undefined</span> : value === null ? <span className="text-ink-3">null</span> : JSON.stringify(value)}
        </dd>
      </React.Fragment>
    ))}
  </dl>
);

const STYLE = `
  @scope {
    .cb-pulse { animation: cb-attr-pulse 900ms var(--tau-ease-out); }
    @media (prefers-reduced-motion: reduce) {
      .cb-pulse { animation: none; }
    }
  }
  @keyframes cb-attr-pulse {
    from { background: var(--tau-accent-soft); }
    to { background: transparent; }
  }
`;

const MethodButton = ({ children, onClick }) => (
  <ui.Button variant="secondary" size="sm" onClick={onClick}>
    <span className="font-tau-mono">{children}</span>
  </ui.Button>
);

const BASE = "https://example.com/articles/attr.html";
const ELEMENTS = [
  { tag: "a", attr: "href", initial: "/docs/guide" },
  { tag: "img", attr: "src", initial: "/images/logo.png" },
  { tag: "link", attr: "href", initial: "/styles/main.css" },
  { tag: "script", attr: "src", initial: "/js/app.js" },
];
const PRESETS = ["/docs/guide", "guide.html", "../images/logo.png", "?page=2", "#intro", "https://cdn.example.org/a.js"];

const Chip = ({ active, children, onClick }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-full border px-3 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Component = () => {
  // 惰性文档：带 <base>，元素在其中解析相对地址，且不会真正发起图片、脚本请求
  const inertDocument = useMemo(() => {
    const doc = document.implementation.createHTMLDocument("");
    const base = doc.createElement("base");
    base.setAttribute("href", BASE);
    doc.head.append(base);
    return doc;
  }, []);
  const elementRef = useRef(null);
  const [kind, setKind] = useState(ELEMENTS[0]);
  const [input, setInput] = useState("#intro");
  const [html, setHtml] = useState("");
  const [values, setValues] = useState({});
  const [version, setVersion] = useState(0);

  const sync = () => {
    const element = elementRef.current;
    if (!element) return;
    setHtml(element.outerHTML);
    setValues({ attribute: element.getAttribute(kind.attr), property: element[kind.attr] });
  };
  useEffect(() => {
    const element = inertDocument.createElement(kind.tag);
    element.setAttribute(kind.attr, kind.initial);
    elementRef.current = element;
    sync();
    return () => {
      elementRef.current = null;
    };
  }, [inertDocument, kind, version]);

  const changeByAttribute = () => {
    elementRef.current.setAttribute(kind.attr, input);
    sync();
  };
  const changeByProperty = () => {
    elementRef.current[kind.attr] = input;
    sync();
  };
  const same = values.attribute === values.property;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="flex flex-wrap items-center gap-2">
        {ELEMENTS.map(item => (
          <Chip key={item.tag} active={kind.tag === item.tag} onClick={() => setKind(item)}>
            {item.tag}
          </Chip>
        ))}
      </div>
      <div className="grid gap-3 @lg:grid-cols-2">
        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-4">
          <div className="flex min-w-0 flex-col gap-1">
            <span className="text-tau-sm text-ink-3">文档基准 URL</span>
            <code className="w-fit min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{BASE}</code>
          </div>
          <div className="flex min-w-0 flex-col gap-1.5">
            <span className="text-tau-sm text-ink-3">要写入的地址</span>
            <ui.Input size="sm" value={input} onChange={event => setInput(event.target.value)} aria-label="要写入的地址" />
            <div className="flex flex-wrap gap-1.5">
              {PRESETS.map(preset => (
                <button
                  key={preset}
                  type="button"
                  onClick={() => setInput(preset)}
                  className="cursor-pointer rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2 hover:bg-press"
                >
                  {preset}
                </button>
              ))}
            </div>
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <span className="text-tau-sm text-ink-3">HTML 文档</span>
          <HtmlView html={html} />
          <Readout
            rows={[
              [`getAttribute("${kind.attr}")`, values.attribute],
              [`${kind.tag}.${kind.attr}`, values.property],
            ]}
          />
          <span className="flex items-center gap-1.5 text-tau-sm text-ink-3">
            对照：<ui.Tag color={same ? "green" : "orange"}>{same ? "两者相同" : "两者不同"}</ui.Tag>
          </span>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <MethodButton onClick={changeByAttribute}>{kind.tag}.setAttribute("{kind.attr}", …)</MethodButton>
        <MethodButton onClick={changeByProperty}>{kind.tag}.{kind.attr} = …</MethodButton>
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} className="ml-auto" onClick={() => setVersion(value => value + 1)}>
          重置
        </ui.Button>
      </div>
    </div>
  );
};
